"use client";

import {
  RiArrowDownSLine,
  RiArrowLeftSLine,
  RiArrowRightSLine,
  RiCalendarLine,
} from "@remixicon/react";
import { motion } from "motion/react";
import { type ReactNode, useEffect, useRef, useState } from "react";
import {
  SegmentedControl,
  SegmentedControlItem,
} from "../../base/segmented-control/segmented-control";
import { Select, SelectItem } from "../../base/select/select";
import { useHydratedReducedMotion } from "../../hooks/use-hydrated-reduced-motion";
import { cx } from "../../utils/cx";
import { formatNumber } from "./chart-card";

export const PALETTE = [2, 6, 5, 3, 8, 7, 1, 4, 9];
export const ink = (index: number) => `var(--color-chart-${PALETTE[index % PALETTE.length]})`;
export const safeRatio = (value: number, max: number) =>
  Number.isFinite(value) && max > 0 ? Math.min(1, Math.max(0, value / max)) : 0;
export const numeric = (value: unknown) =>
  typeof value === "number" && Number.isFinite(value) ? value : 0;
export const sum = (values: number[]) => values.reduce((total, value) => total + numeric(value), 0);
export const average = (values: number[]) => (values.length ? sum(values) / values.length : 0);
export const shortNumber = (value: number) =>
  Math.abs(value) >= 1000 ? `${+(value / 1000).toFixed(1)}K` : `${+value.toFixed(1)}`;
export const MONTHS = [
  "Jan",
  "Feb",
  "Mar",
  "Apr",
  "May",
  "Jun",
  "Jul",
  "Aug",
  "Sep",
  "Oct",
  "Nov",
  "Dec",
];
export const DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
export const chartAxis = {
  tickLine: false,
  axisLine: false,
  tick: { fontSize: 12, fill: "var(--color-text-tertiary)" },
} as const;
export interface ChartRange {
  id: string;
  label: string;
  delta?: number;
  headline?: number;
}
export interface ChartCommonProps {
  title?: string;
  headline?: number;
  delta?: number;
  range?: string;
  defaultRange?: string;
  onRangeChange?: (id: string) => void;
  className?: string;
  format?: (value: number) => string;
}
export function useChartRange<T extends ChartRange>(
  ranges: T[] | undefined,
  defaultRange?: string,
  onChange?: (id: string) => void,
) {
  const [selected, setSelected] = useState(defaultRange ?? ranges?.[0]?.id);
  const current = ranges?.find((range) => range.id === selected) ?? ranges?.[0];
  const select = (id: string) => {
    setSelected(id);
    onChange?.(id);
  };
  return { current, id: current?.id, select };
}
export function PeriodSelect({
  ranges,
  selected,
  onChange,
  label = "This year",
}: {
  ranges?: ChartRange[];
  selected?: string;
  onChange: (id: string) => void;
  label?: string;
}) {
  const content = (
    <>
      <RiCalendarLine className="size-4 shrink-0 text-text-secondary" />
      <span>{label}</span>
    </>
  );
  if (!ranges?.length)
    return (
      <span className="flex h-8 shrink-0 items-center gap-1.5 rounded-2lg border border-border-button-default bg-background-primary-default px-2 text-body-medium text-text-primary shadow-xs">
        {content}
      </span>
    );
  return (
    <Select
      aria-label="Change period"
      selectedKey={selected}
      onSelectionChange={(key) => key != null && onChange(String(key))}
      triggerClassName="h-8 pl-2 pr-1.5 py-1 text-body-medium"
      className="shrink-0"
      renderValue={<span className="flex items-center gap-1.5">{content}</span>}
      renderIndicator={(open) => (
        <RiArrowDownSLine
          className={cx(
            "size-4 shrink-0 text-text-secondary transition-transform duration-200 ease-out",
            open && "rotate-180",
          )}
        />
      )}
    >
      <>
        {ranges.map((range) => (
          <SelectItem key={range.id} id={range.id}>
            {range.label}
          </SelectItem>
        ))}
      </>
    </Select>
  );
}
export function PeriodTabs({
  ranges,
  selected,
  onChange,
  plain = false,
}: {
  ranges: ChartRange[];
  selected?: string;
  onChange: (id: string) => void;
  plain?: boolean;
}) {
  return (
    <SegmentedControl
      aria-label="Chart period"
      variant={plain ? "plain" : "solid"}
      className={cx("shrink-0 bg-transparent", plain && "[&>button]:py-0")}
      selectedKeys={selected ? [selected] : []}
      onSelectionChange={(keys) => {
        const id = [...keys][0];
        if (id != null) onChange(String(id));
      }}
    >
      {ranges.map((range) => (
        <SegmentedControlItem id={range.id} key={range.id}>
          {range.label}
        </SegmentedControlItem>
      ))}
    </SegmentedControl>
  );
}
export function WeekSwitcher({
  label,
  onPrevious,
  onNext,
}: {
  label: string;
  onPrevious: () => void;
  onNext: () => void;
}) {
  return (
    <div className="flex h-8 shrink-0 items-center gap-1 rounded-2lg border border-border-button-default bg-background-primary-default px-1 shadow-xs">
      <button
        type="button"
        aria-label="Previous period"
        onClick={onPrevious}
        className="rounded-md text-text-secondary outline-none focus-visible:ring-2 focus-visible:ring-border-focus-ring"
      >
        <RiArrowLeftSLine className="size-4" />
      </button>
      <span className="min-w-20 text-center text-body-medium text-text-primary">{label}</span>
      <button
        type="button"
        aria-label="Next period"
        onClick={onNext}
        className="rounded-md text-text-secondary outline-none focus-visible:ring-2 focus-visible:ring-border-focus-ring"
      >
        <RiArrowRightSLine className="size-4" />
      </button>
    </div>
  );
}
export function AnimatedNumber({
  value,
  format = formatNumber,
}: {
  value: number;
  format?: (value: number) => string;
}) {
  const reduced = useHydratedReducedMotion();
  const [display, setDisplay] = useState(value);
  const current = useRef(value);
  useEffect(() => {
    if (reduced) {
      current.current = value;
      setDisplay(value);
      return;
    }
    const from = current.current,
      start = performance.now();
    let frame = 0;
    const tick = (time: number) => {
      const t = Math.min(1, (time - start) / 300);
      current.current = from + (value - from) * (1 - (1 - t) ** 3);
      setDisplay(current.current);
      if (t < 1) frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [value, reduced]);
  return <>{format(reduced ? value : display)}</>;
}
export function ChartFrame({
  title,
  value,
  delta,
  format,
  suffix,
  action,
  children,
  className,
  height,
  footer,
  heading,
}: {
  title: string;
  value?: number;
  delta?: number;
  format?: (value: number) => string;
  suffix?: ReactNode;
  action?: ReactNode;
  children: ReactNode;
  className?: string;
  height?: number;
  footer?: ReactNode;
  heading?: ReactNode;
}) {
  return (
    <section
      className={cx(
        "flex w-full min-w-0 flex-col gap-4 rounded-2xl bg-background-secondary-default px-4 pt-4 pb-3",
        className,
      )}
      style={height ? { height } : undefined}
    >
      <div className="flex w-full flex-wrap items-start justify-between gap-3">
        <div className="flex min-w-0 flex-1 flex-col gap-0.5">
          <p className="truncate text-body-medium text-text-secondary">{title}</p>
          <div className="flex items-center gap-2">
            <p className="whitespace-nowrap text-title-1-medium text-text-primary tabular-nums">
              {heading ?? (value != null && <AnimatedNumber value={value} format={format} />)}
              {suffix && (
                <span className="ml-1 text-caption-1-medium text-text-secondary">{suffix}</span>
              )}
            </p>
            {delta != null && (
              <span
                className={cx(
                  "rounded-md px-1.5 py-0.5 text-body-medium whitespace-nowrap",
                  delta >= 0
                    ? "bg-status-lime-background text-status-lime-text"
                    : "bg-status-rose-background text-status-rose-text",
                )}
              >
                {delta > 0 ? "+" : ""}
                {+(delta * 100).toFixed(1)}%
              </span>
            )}
          </div>
        </div>
        {action}
      </div>
      {children}
      {footer}
    </section>
  );
}
export interface StatTile {
  label: string;
  value: ReactNode;
  color?: string;
}
export function StatTiles({
  items,
  active,
  onHover,
  columns = 3,
}: {
  items: StatTile[];
  columns?: number;
  active?: number | null;
  onHover?: (index: number | null) => void;
}) {
  return (
    <div className="-mx-2 -mb-1 flex flex-wrap gap-2">
      {items.map((item, index) => (
        <div
          key={item.label}
          tabIndex={onHover ? 0 : undefined}
          onMouseEnter={() => onHover?.(index)}
          onMouseLeave={() => onHover?.(null)}
          onFocus={() => onHover?.(index)}
          onBlur={() => onHover?.(null)}
          className="flex min-w-0 flex-auto basis-[calc(33.333%-8px)] flex-col gap-px rounded-2lg bg-background-inner-default px-2.5 py-2 outline-none transition-opacity duration-200 motion-reduce:transition-none focus-visible:ring-2 focus-visible:ring-border-focus-ring"
          style={{
            opacity: active != null && active !== index ? 0.35 : 1,
            flexBasis: `calc(${100 / columns}% - 8px)`,
          }}
        >
          <span className="flex items-center gap-1.5 truncate text-body-regular text-text-secondary">
            {item.color && (
              <span className="size-3 shrink-0 rounded-[4px]" style={{ background: item.color }} />
            )}
            {item.label}
          </span>
          <span className="text-body-medium text-text-primary tabular-nums">{item.value}</span>
        </div>
      ))}
    </div>
  );
}
export function PulseDot({ cx: x, cy: y, stroke }: { cx?: number; cy?: number; stroke?: string }) {
  const reduced = useHydratedReducedMotion();
  if (x == null || y == null) return null;
  return (
    <g>
      <motion.circle
        key={reduced ? "reduced" : "animated"}
        cx={x}
        cy={y}
        fill={stroke}
        initial={false}
        animate={reduced ? { r: 7, opacity: 0.2 } : { r: [5, 11, 5], opacity: [0.25, 0, 0.25] }}
        transition={reduced ? { duration: 0 } : { duration: 1.6, repeat: Infinity }}
      />
      <circle
        cx={x}
        cy={y}
        r={3.5}
        fill={stroke}
        stroke="var(--color-background-inner-default)"
        strokeWidth={2}
      />
    </g>
  );
}

"use client";
import { useMemo, useState } from "react";
import { ResponsiveContainer, Sankey } from "recharts";
import {
  type ChartCommonProps,
  ChartFrame,
  type ChartRange,
  ink,
  PeriodSelect,
  sum,
  useChartRange,
} from "./pro-chart";
import { SANKEY_DEMO_RANGES } from "./sankey-demo-data";
export interface SankeyNode {
  name: string;
  color?: string;
}
export interface SankeyLink {
  source: string | number;
  target: string | number;
  value: number;
}
export interface SankeyChartRange extends ChartRange {
  nodes?: SankeyNode[];
  links: SankeyLink[];
}
export interface SankeyChartCardProps extends ChartCommonProps {
  nodes?: SankeyNode[];
  links?: SankeyLink[];
  ranges?: SankeyChartRange[];
  axisLabels?: [string, string];
  linkColor?: "source" | "target";
}
export const SANKEY_NODES: SankeyNode[] = [
  { name: "Focus", color: "var(--color-chart-7)" },
  { name: "Meetings", color: "var(--color-chart-5)" },
  { name: "Breaks", color: "var(--color-chart-8)" },
  { name: "Admin", color: "var(--color-chart-6)" },
  { name: "Learning", color: "var(--color-chart-3)" },
  ...[
    "Browsing",
    "Writing",
    "Messaging",
    "Productivity",
    "Email",
    "Video calls",
    "Everything else",
  ].map((name) => ({ name, color: "neutral" })),
];
export const SANKEY_LINKS: SankeyLink[] = SANKEY_DEMO_RANGES[0].links;
const RANGES: SankeyChartRange[] = SANKEY_DEMO_RANGES;
interface LayoutNode {
  x?: number;
  y?: number;
  width?: number;
  height?: number;
  index?: number;
  payload?: { name?: string; value?: number; sourceLinks?: number[]; targetLinks?: number[] };
}
interface LayoutLink {
  index?: number;
  sourceX?: number;
  sourceY?: number;
  targetX?: number;
  targetY?: number;
  sourceControlX?: number;
  targetControlX?: number;
  linkWidth?: number;
  payload?: {
    source?: { index?: number; name?: string };
    target?: { index?: number; name?: string };
    value?: number;
  };
}
export function SankeyChartCard({
  nodes,
  links,
  ranges: supplied,
  title = "Tracked time",
  axisLabels = ["Tracked time", "Share of tracked time"],
  linkColor = "source",
  ...props
}: SankeyChartCardProps = {}) {
  const ranges = supplied ?? (links ? undefined : RANGES),
    period = useChartRange(ranges, props.defaultRange, props.onRangeChange),
    items = period.current?.nodes ?? nodes ?? SANKEY_NODES,
    raw = period.current?.links ?? links ?? SANKEY_LINKS,
    [active, setActive] = useState<number | null>(null),
    [activeLink, setActiveLink] = useState<number | null>(null),
    [layoutHeight, setLayoutHeight] = useState(0),
    format = props.format ?? ((n: number) => `${+n.toFixed(1)}h`);
  const data = useMemo(
    () => ({
      nodes: items.map((n) => ({ ...n })),
      links: raw
        .map((l) => ({
          ...l,
          source:
            typeof l.source === "number" ? l.source : items.findIndex((n) => n.name === l.source),
          target:
            typeof l.target === "number" ? l.target : items.findIndex((n) => n.name === l.target),
        }))
        .filter(
          (l) =>
            l.source >= 0 &&
            l.target >= 0 &&
            l.source < items.length &&
            l.target < items.length &&
            l.source !== l.target &&
            Number.isFinite(l.value) &&
            l.value > 0,
        ),
    }),
    [items, raw],
  );
  const sources = data.nodes
      .map((_, i) => i)
      .filter((i) => !data.links.some((l) => l.target === i)),
    total = sum(data.links.filter((l) => sources.includes(l.source)).map((l) => l.value)),
    related = (i: number) =>
      activeLink != null
        ? data.links[activeLink]?.source === i || data.links[activeLink]?.target === i
        : active == null ||
          active === i ||
          data.links.some(
            (l) =>
              (l.source === active && l.target === i) || (l.target === active && l.source === i),
          ),
    nodeValue = (i: number) =>
      Math.max(
        sum(data.links.filter((l) => l.source === i).map((l) => l.value)),
        sum(data.links.filter((l) => l.target === i).map((l) => l.value)),
      ),
    color = (i: number) =>
      items[i]?.color === "neutral"
        ? "light-dark(var(--color-neutral-400), var(--color-neutral-300))"
        : (items[i]?.color ?? ink(i));
  const focusedLink = activeLink == null ? undefined : data.links[activeLink];
  const clearActive = () => {
    setActive(null);
    setActiveLink(null);
  };
  const selectNode = (index: number) => {
    setActive(index);
    setActiveLink(null);
  };
  const Node = ({ x = 0, y = 0, width = 12, height = 0, index = 0 }: LayoutNode) => {
    const source = sources.includes(index),
      value = nodeValue(index);
    const w = Math.max(0, width),
      h = Math.max(0, height),
      radius = Math.min(5, w / 2, h / 2);
    const end = x + w,
      bottom = y + h;
    // Round the outside edge; the ribbon-facing edge stays flush with the links.
    const path = source
      ? `M${x + radius},${y} H${end} V${bottom} H${x + radius} A${radius},${radius} 0 0 1 ${x},${bottom - radius} V${y + radius} A${radius},${radius} 0 0 1 ${x + radius},${y} Z`
      : `M${x},${y} H${end - radius} A${radius},${radius} 0 0 1 ${end},${y + radius} V${bottom - radius} A${radius},${radius} 0 0 1 ${end - radius},${bottom} H${x} Z`;
    const fill =
      active === index
        ? items[index]?.color === "neutral"
          ? "light-dark(var(--color-neutral-500), var(--color-neutral-100))"
          : color(index).replace(/var\(--color-chart-(\d+)\)/, "var(--color-chart-$1-active)")
        : color(index);
    return (
      <g
        tabIndex={0}
        role="button"
        aria-label={`${items[index]?.name}: ${format(value)}`}
        onFocus={() => selectNode(index)}
        onBlur={clearActive}
        opacity={related(index) ? 1 : 0.35}
        onMouseEnter={() => selectNode(index)}
        onMouseLeave={clearActive}
        className="transition-opacity duration-200 ease-out motion-reduce:transition-none"
      >
        <path
          d={path}
          fill={fill}
          className="transition-[fill] duration-150 ease-out motion-reduce:transition-none"
        />
        {source ? (
          <g className="pointer-events-none">
            <text
              x={x - 8}
              y={y + h / 2}
              dy={-2}
              textAnchor="end"
              fontSize={13}
              fontWeight={500}
              fill="var(--color-text-primary)"
            >
              {items[index]?.name}
            </text>
            <text
              x={x - 8}
              y={y + h / 2}
              dy={14}
              textAnchor="end"
              fontSize={12}
              fill="var(--color-text-tertiary)"
              className="tabular-nums"
            >
              {format(value)}
            </text>
          </g>
        ) : (
          <text
            x={end + 8}
            y={y + h / 2}
            dy={4}
            textAnchor="start"
            fontSize={13}
            className="pointer-events-none"
          >
            <tspan fontWeight={500} fill="var(--color-text-primary)">
              {items[index]?.name}
            </tspan>
            <tspan
              fill="var(--color-text-tertiary)"
              className="tabular-nums"
            >{` · ${total ? Math.round((value / total) * 100) : 0}%`}</tspan>
          </text>
        )}
      </g>
    );
  };
  const Link = ({
    index = 0,
    sourceX = 0,
    sourceY = 0,
    targetX = 0,
    targetY = 0,
    sourceControlX = 0,
    targetControlX = 0,
    linkWidth = 0,
    payload,
  }: LayoutLink) => {
    const source =
        payload?.source?.index ?? items.findIndex((n) => n.name === payload?.source?.name),
      target = payload?.target?.index ?? items.findIndex((n) => n.name === payload?.target?.name);
    return (
      <path
        d={`M${sourceX},${sourceY} C${sourceControlX},${sourceY} ${targetControlX},${targetY} ${targetX},${targetY}`}
        fill="none"
        stroke={color(linkColor === "source" ? source : target)}
        strokeWidth={Math.max(0, linkWidth)}
        strokeOpacity={
          activeLink != null
            ? activeLink === index
              ? 0.7
              : 0.08
            : active == null
              ? 0.32
              : active === source || active === target
                ? 0.7
                : 0.08
        }
        onMouseEnter={() => {
          setActiveLink(index);
          setActive(null);
        }}
        onMouseLeave={clearActive}
        className="transition-[stroke-opacity] duration-200 ease-out motion-reduce:transition-none"
      />
    );
  };
  return (
    <ChartFrame
      title={
        focusedLink
          ? `${items[focusedLink.source]?.name} → ${items[focusedLink.target]?.name}`
          : active == null
            ? title
            : (items[active]?.name ?? title)
      }
      value={
        focusedLink
          ? focusedLink.value
          : active == null
            ? (period.current?.headline ?? props.headline ?? total)
            : nodeValue(active)
      }
      format={format}
      delta={period.current?.delta ?? props.delta}
      className={props.className}
      height={480}
      action={
        <PeriodSelect
          ranges={ranges}
          selected={period.id}
          onChange={(id) => {
            clearActive();
            period.select(id);
          }}
          label={period.current?.label ?? props.range ?? "This week"}
        />
      }
    >
      <div className="relative min-h-0 w-full flex-1">
        <ResponsiveContainer
          width="100%"
          height="100%"
          onResize={(_, height) => setLayoutHeight(height)}
        >
          {/* ResizeObserver gives unscaled CSS dimensions. The initial bounding rect can
              be smaller inside transformed previews, leaving less room than the node gaps. */}
          {layoutHeight > 0 ? (
            <Sankey
              data={data}
              node={Node}
              link={Link}
              nodeWidth={12}
              linkCurvature={0.55}
              nodePadding={Math.min(
                14,
                Math.max(0, (layoutHeight - 4) / Math.max(1, items.length)),
              )}
              iterations={32}
              sort={false}
              margin={{ top: 2, right: 150, bottom: 2, left: 88 }}
            />
          ) : (
            <div />
          )}
        </ResponsiveContainer>
      </div>
      <div className="flex w-full justify-between pb-1 text-caption-1-medium text-text-tertiary">
        <span>{axisLabels[0]}</span>
        <span>{axisLabels[1]}</span>
      </div>
    </ChartFrame>
  );
}

